import{_ as p,a0 as o,w as d,s as u,I as i,x as a,a1 as t,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"在 Linux Mint 中安装 KDE Plasma 桌面环境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux Mint 中安装 KDE Plasma 桌面环境 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux Mint 中安装 KDE Plasma 桌面环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux Mint 中安装 KDE Plasma 桌面环境 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment","title":"在 Linux Mint 中安装 KDE Plasma 桌面环境","tag":"202308","desc":""},"relativePath":"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment.md","filePath":"[post].md"}'),r={name:"202308/20230721.4 ⭐️ Install KDE Plasma Desktop in Linux Mint An Experiment.md"};function g(h,s,m,k,b,x){const n=o("Link");return d(),u("div",null,[s[19]||(s[19]=i("h1",{id:"在-linux-mint-中安装-kde-plasma-桌面环境",tabindex:"-1"},[a("在 Linux Mint 中安装 KDE Plasma 桌面环境 "),i("a",{class:"header-anchor",href:"#在-linux-mint-中安装-kde-plasma-桌面环境","aria-label":"Permalink to “在 Linux Mint 中安装 KDE Plasma 桌面环境”"},"​")],-1)),s[20]||(s[20]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/10/153023isl2b4y771f34h79.jpg",alt:""})],-1)),s[21]||(s[21]=i("blockquote",null,[i("p",null,"下面介绍如何在 Linux Mint 中安装 KDE Plasma 桌面环境，并进行了一些微调。")],-1)),i("p",null,[t(n,{href:"https://www.debugpoint.com/linux-mint"},{default:e(()=>[...s[0]||(s[0]=[a("Linux Mint",-1)])]),_:1}),s[1]||(s[1]=a(" 是最流行的和用户友好的 Linux 发行版，以其易用性和稳定性而闻名。虽然 Linux Mint 中默认的 Cinnamon 桌面环境提供了友好愉快的体验，但也有一些用户可能想要探索其它的桌面环境，以进一步定制自己的 Linux 体验。KDE Plasma 是另一个著名的桌面环境，提供了一种现代化的特色功能丰富的界面。",-1))]),s[22]||(s[22]=l('<p>然而，Linux Mint 从未正式提供过 KDE Plasma 。但是这里有一种在 Linux Mint 基础之上安装 KDE Plasma 桌面环境的方法。让我们一起尝试一下。</p><blockquote><p><strong>注意</strong>: 不要在你的有重要数据的稳定系统中尝试这些步骤。有风险。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Linux-Mint-with-KDE-Plasma.jpg" alt="Linux Mint with KDE Plasma"></p><h3 id="在-linux-mint-中安装-kde-plasma-桌面环境-1" tabindex="-1">在 Linux Mint 中安装 KDE Plasma 桌面环境 <a class="header-anchor" href="#在-linux-mint-中安装-kde-plasma-桌面环境-1" aria-label="Permalink to “在 Linux Mint 中安装 KDE Plasma 桌面环境”">​</a></h3><p>在 Linux Mint 发行版中，有三种主要组件来安装 KDE Plasma 桌面环境。它们是 <code>kde-full</code>、<code>kde-standard</code> 和 <code>kde-plasma-desktop</code> 。</p>',5)),i("p",null,[t(n,{href:"https://packages.ubuntu.com/kinetic/kde-full"},{default:e(()=>[...s[2]||(s[2]=[a("kde-full",-1)])]),_:1}),s[3]||(s[3]=a(" 软件包集包含完整的 KDE Plasma 桌面环境。kde-standard 是最小的版本，kde-plasma-desktop 仅是桌面环境。",-1))]),s[23]||(s[23]=l(`<p>如果你将要尝试安装 KDE Plasma 桌面环境，我将建议安装 kde-full 软件包。</p><p>首先，打开一个终端，确保你的 Linux Mint 版本是已更新的。确保你执行了一次重新启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>其次，在终端中，运行下面的命令来安装完整的 KDE 软件包。由于 Linux Mint 是基于 Ubuntu LTS 版本的，所以，你应该会获取基于当前正在持续更新的 Kubuntu LTS Plasma 版本的 KDE Plasma 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kde-full</span></span></code></pre></div><p>完整的下载体积有点大。针对当前的 Linux Mint 版本，它大约是 1.5 GB ，整个安装过程可能需要 20 分钟。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Installing-KDE-Plasma-in-Linux-Mint.jpg" alt="Installing KDE Plasma in Linux Mint"></p><p>在安装过程中，你需要选择显示管理器，因为 KDE Plasma 使用 SDDM 。出现提示时，在下面的屏幕中选择 SDDM 。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Selecting-SDDM-as-display-manager.jpg" alt="Selecting SDDM as display manager"></p><p>在安装完成后，你需要在 SDDM 配置文件中修改其中一个备选项以阻止在登录过程中弹出一个空的联机键盘。为此，使用 nano 或任意一个编辑器来打开下面的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/sddm.conf</span></span></code></pre></div><p>接下来，添加下面的行。保存并退出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[General]InputMethod=</span></span></code></pre></div><p>最后，重新启动系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>在登录期间，你应该会看到 SDDM 登录窗口，而不是 Linux Mint 的原来的登录提示窗口。在窗口顶部，选择 “Plasma” 会话并登录。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Choose-Plasma-as-Session.jpg" alt="Choose Plasma as Session"></p><h3 id="移除-cinnamon-、xfce-或-mate" tabindex="-1">移除 Cinnamon 、Xfce 或 MATE <a class="header-anchor" href="#移除-cinnamon-、xfce-或-mate" aria-label="Permalink to “移除 Cinnamon 、Xfce 或 MATE”">​</a></h3><p>在 KDE Plasma 安装后，你可以移除 Cinnamon 、Xfce 或 MATE 桌面环境组件。如果你看到你的 KDE Plasma 工作的很好，那么移除是安全的。使用下面的命令来移除它们，最后使用命令 <code>reboot</code> 来重新启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge cinnamon</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge mate-desktop</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge</span></span>
<span class="line"><span>    xfce4-session</span></span>
<span class="line"><span>    xfwm4</span></span>
<span class="line"><span>    xfdesktop4</span></span>
<span class="line"><span>    xfconf</span></span>
<span class="line"><span>    xfce4-utils</span></span>
<span class="line"><span>    exo-utils</span></span>
<span class="line"><span>    xfce4-panel</span></span>
<span class="line"><span>    xfce4-terminal</span></span>
<span class="line"><span>    thunar</span></span></code></pre></div><h3 id="几点注意事项" tabindex="-1">几点注意事项 <a class="header-anchor" href="#几点注意事项" aria-label="Permalink to “几点注意事项”">​</a></h3><ul><li>你可能会发现：相比于 Cinnamon 桌面环境，KDE Plasma 的运行性能有一点慢，这是很明显的。</li><li>Linux Mint 的壁纸、主题、图标和光标文件可能会保留在系统中。如果你想的话，你可以移除它们。</li><li>Mint Plymouth 动画应该也会保留，你可以手动移除它。</li><li>如果你在一个虚拟机中的系统中使用上述步骤，在从待机状态唤醒时，SDDM 可能会崩溃。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>热烈庆贺！你已经在你的 Linux Mint 系统上成功的安装 Plasma 桌面环境。通过执行这些步骤，你现在可以访问一个功能丰富的、视觉震撼的、可高度自定义的桌面环境。请谨慎使用！</p><p><em>（题图：MJ/8944ad54-b64c-4761-b848-801215c63b56）</em></p><hr>`,29)),i("p",null,[s[5]||(s[5]=a("via: ",-1)),t(n,{href:"https://www.debugpoint.com/kde-plasma-linux-mint/"},{default:e(()=>[...s[4]||(s[4]=[a("https://www.debugpoint.com/kde-plasma-linux-mint/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),t(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...s[6]||(s[6]=[a("Arindam",-1)])]),_:1}),s[11]||(s[11]=a(" 选题：",-1)),t(n,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[7]||(s[7]=[a("lkxed",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),t(n,{href:"https://github.com/robsean"},{default:e(()=>[...s[8]||(s[8]=[a("robsean",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const P=p(r,[["render",g]]);export{D as __pageData,P as default};
